//! Labels of the editor page (`text/<locale>/editor.ron`, one folder per
//! language, built into the binary). A missing label falls back to `en`.

use crate::texts::TextFile;
use std::collections::BTreeMap;

// `FILES`: generated by `build.rs` from the folders of `text/`.
include!(concat!(env!("OUT_DIR"), "/editor_files.rs"));

/// The languages of the editor page itself.
pub fn page_locales() -> Vec<&'static str> {
    FILES.iter().map(|(c, _)| *c).collect()
}

fn entries(code: &str) -> BTreeMap<String, String> {
    FILES
        .iter()
        .find(|(c, _)| *c == code)
        .and_then(|(_, t)| TextFile::parse(t).ok())
        .map(|f| {
            f.entries
                .into_iter()
                .map(|(k, e)| (k, e.text().to_owned()))
                .collect()
        })
        .unwrap_or_default()
}

/// Every label in `locale`, English where missing.
pub fn texts(locale: &str) -> BTreeMap<String, String> {
    let mut out = entries("en");
    out.extend(entries(locale));
    out
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::expect_used, clippy::indexing_slicing)]
mod tests {
    use super::*;
    use i18n::{KeyTable, Locale, Severity};

    #[test]
    fn labels_exist_in_every_locale_of_the_page() {
        let en = [("editor.ron", FILES[0].1)];
        let keys = KeyTable::from_source(&en).unwrap();
        for (code, text) in FILES {
            let l: Locale = code.parse().unwrap();
            let problems: Vec<_> = i18n::check_locale(&keys, l, &[("editor.ron", text)])
                .into_iter()
                .filter(|p| p.severity() == Severity::Error)
                .collect();
            assert!(problems.is_empty(), "{l:?}: {problems:?}");
            assert_eq!(entries(l.code()).len(), keys.len(), "{l:?}");
        }
    }

    /// P12: each piece the loader messages are cut into has a label.
    #[test]
    fn every_problem_piece_has_a_label() {
        let en = entries("en");
        for (key, _) in defs::PROBLEM_TEMPLATES {
            assert!(en.contains_key(&format!("editor.problem.{key}")), "{key}");
        }
    }

    #[test]
    fn every_label_the_page_uses_exists() {
        let page = [
            include_str!("../web/app.js"),
            include_str!("../web/looks.js"),
            include_str!("../web/langs.js"),
            include_str!("../web/sounds.js"),
            include_str!("../web/game.js"),
            include_str!("../web/theme.js"),
            include_str!("../web/admin.js"),
            include_str!("../web/replays.js"),
        ]
        .concat();
        let page = page.as_str();
        let labels = texts("en");
        let mut rest = page;
        while let Some(i) = rest.find("t(\"editor.") {
            let after = &rest[i + 3..];
            let end = after.find('"').unwrap();
            let key = &after[..end];
            // `"editor.kind." + kind` is checked below for every kind.
            assert!(
                key.ends_with('.') || key.ends_with('_') || labels.contains_key(key),
                "the page uses `{key}` with no label"
            );
            rest = &after[end..];
        }
        for k in defs::editor::KINDS.iter().map(|k| k.name).chain(["raw"]) {
            assert!(
                labels.contains_key(&format!("editor.kind.{k}")),
                "kind `{k}` has no label"
            );
        }
    }

    /// The page's scripts share one global scope: a second top-level
    /// `function x` silently replaces the first.
    #[test]
    fn no_two_scripts_define_the_same_name() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("web");
        let mut seen = std::collections::BTreeMap::new();
        let mut files: Vec<_> = std::fs::read_dir(&dir)
            .unwrap()
            .flatten()
            .map(|e| e.path())
            .filter(|p| p.extension().is_some_and(|x| x == "js"))
            .collect();
        files.sort();
        for path in files {
            let file = path.file_name().unwrap().to_string_lossy().into_owned();
            for line in std::fs::read_to_string(&path).unwrap().lines() {
                let rest = ["async function ", "function ", "const ", "let ", "var "]
                    .iter()
                    .find_map(|p| line.strip_prefix(p));
                let Some(rest) = rest else { continue };
                let name: String = rest
                    .chars()
                    .take_while(|c| c.is_alphanumeric() || *c == '_' || *c == '$')
                    .collect();
                if name.is_empty() {
                    continue;
                }
                if let Some(first) = seen.insert(name.clone(), file.clone()) {
                    assert_eq!(first, file, "`{name}` is defined in {first} and {file}");
                }
            }
        }
    }
}
